export const GRID_5 = 'display: grid;\ngrid-template-columns: repeat(5, 1fr);\ngrid-template-rows: repeat(5, 1fr);\ngap: 6px;';
export const GRID_3 = 'display: grid;\ngrid-template-columns: repeat(3, 1fr);\ngrid-template-rows: repeat(3, 1fr);\ngap: 8px;';
export const GRID_TALL = 'display: grid;\ngrid-template-columns: repeat(3, 1fr);\ngrid-template-rows: repeat(2, 1fr);\ngap: 8px;';
export const DESIGN_PROPS = ['display', 'grid-template-columns', 'grid-template-rows', 'grid-template-areas', 'grid-template', 'gap', 'grid-column', 'grid-row', 'grid-area'];
export const areaRule = (selector: string): BoardRuleDraft => ({ s: '.' + selector, f: 'grid-area: ' + selector + ';', ed: false });
export const hiddenRule = (selector: string): BoardRuleDraft => ({ s: '.' + selector, f: 'grid-area: ' + selector + ';', ed: false, oculto: true });
export const fixedRule = (selector: string, css: string): BoardRuleDraft => ({ s: '.' + selector, f: css, ed: false });
export const VERTICAL_RIVER = fixedRule('rio', 'grid-column: 3;\ngrid-row: 1 / -1;');
export const horizontalRiver = (row: number): BoardRuleDraft => fixedRule('rio', `grid-column: 1 / -1;\ngrid-row: ${row};`);
export const FOREST_9 = ['arbol', 'pino', 'arbol', 'pino', 'arbol', 'pino', 'arbol', 'pino', 'arbol'];
export const LAKE_6 = ['barca', 'pez', 'barca', 'pez', 'barca', 'pez'];

